package calc

func fib(n int64) int64 {
	if n < 1 {
		return n
	}
	return fib(n-1) + fib(n-2)
}

package calc

import "testing"

func TestFib(t *testing.T) {
	if got := fib(0); got != 0 {
		t.Errorf("fib(0) = %d, want 0", got)
	}
	if got := fib(1); got != 1 {
		t.Errorf("fib(1) = %d, want 1", got)
	}
	if got := fib(10); got != 55 {
		t.Errorf("fib(10) = %d, want 55", got)
	}
	if got := fib(20); got != 6765 {
		t.Errorf("fib(20) = %d, want 6765", got)
	}
}
